independent_browser.fixture_builder:
import fs from "node:fs";
import {pathToFileURL} from "node:url";
const root=process.argv[2];
const {createWeekPlan}=await import(pathToFileURL(root+"/original/static/week_plan.mjs"));
const {makeWeekFile}=await import(pathToFileURL(root+"/original/static/week_file.mjs"));
const response=JSON.parse(fs.readFileSync(root+"/saved-week-response.json","utf8"));
const inputs={cuisines:["Cuban","Mexican"],music:["Celia Cruz"],films:["West Side Story"],city:"Pasadena",constraints:response.comparison.constraints};
function make(res){return JSON.parse(makeWeekFile({response:res,inputs,state:createWeekPlan(res,"2026-10-12"),receivedAt:"2026-10-12T10:00:00.000Z",calendarId:"0123456789abcdef0123456789abcdef"},new Date("2026-10-13T00:00:00.000Z")).text);}
const zero=make(response);
const positiveResponse=structuredClone(response);
["with_qloo_entity_id","with_affinity_evidence","constraint_checked","unsafe_candidates_rejected"].forEach((key,i)=>{positiveResponse.comparison.llm_only[key]=i+1;});
const positive=make(positiveResponse);
const missing=structuredClone(zero);delete missing.response.comparison.llm_only.constraint_checked;
const absent=structuredClone(zero);absent.response.comparison.llm_only.unsafe_candidates_rejected=null;
for(const [name,value] of Object.entries({zero,positive,missing,null:absent}))fs.writeFileSync(root+"/fixtures/"+name+".json",JSON.stringify(value,null,2)+"\n",{flag:"wx"});
console.log(JSON.stringify({created:["zero.json","positive.json","missing.json","null.json"],node:process.version}));
